uint32_t pc=entry&0x1fffffffu;
if(pc<=0x0c03ef02u) return vf3_away_batch64_adapter_0(entry,s,ram);
if(pc<=0x0c0557aau) return vf3_away_batch64_adapter_1(entry,s,ram);
